class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        char_map = {}
        l = 0
        max_len = 0
        for r, c in enumerate(s):
            if c in char_map and char_map[c] >= l:
                l = char_map[c] + 1
            char_map[c] = r
            max_len = max(max_len, r - l + 1)
        return max_len

