function lengthOfLongestSubstring(s) {
    const map = new Map();
    let l = 0, maxLen = 0;
    for (let r = 0; r < s.length; r++) {
        const c = s[r];
        if (map.has(c) && map.get(c) >= l) l = map.get(c) + 1;
        map.set(c, r);
        maxLen = Math.max(maxLen, r - l + 1);
    }
    return maxLen;
}
